BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'complete_read_committed_required'; END IF;
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR octet_length(p_request::text)>8192 OR
 (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_request) key) IS DISTINCT FROM ARRAY['attempt','expectedArtifactManifestHash','expectedCalculatorExecutionHash','jobId','owner','preparationHash','preparationId','reservationId','scope','snapshotHash']
 OR p_request->>'scope' IS DISTINCT FROM 'research_observed_v1' OR jsonb_typeof(p_request->'owner') IS DISTINCT FROM 'string' OR p_request->>'owner' !~ '^[A-Za-z0-9:_-]{3,120}$'
 OR jsonb_typeof(p_request->'attempt') IS DISTINCT FROM 'number' OR p_request->>'attempt' !~ '^[1-3]$' THEN RAISE EXCEPTION 'complete_request_shape';END IF;
 IF EXISTS(SELECT FROM jsonb_each(p_request) WHERE key IN ('jobId','reservationId','preparationId') AND (jsonb_typeof(value)<>'string' OR value#>>'{}' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'))
 OR EXISTS(SELECT FROM jsonb_each(p_request) WHERE key IN ('snapshotHash','preparationHash','expectedArtifactManifestHash','expectedCalculatorExecutionHash') AND (jsonb_typeof(value)<>'string' OR value#>>'{}' !~ '^[a-f0-9]{64}$')) THEN RAISE EXCEPTION 'complete_request_shape';END IF;
 PERFORM pg_advisory_xact_lock(610091002::bigint);PERFORM pg_advisory_xact_lock(2409,6002);
 SELECT * INTO old FROM public.research_input_preparations_v2 WHERE preparation_id=(p_request->>'preparationId')::uuid;
 IF old.preparation_id IS NULL OR old.input_hash IS DISTINCT FROM p_request->>'preparationHash'
 OR (old.request-'sourceDocumentIds'-'bundleId') IS DISTINCT FROM (p_request-'preparationId'-'preparationHash'-'expectedArtifactManifestHash'-'expectedCalculatorExecutionHash') THEN RAISE EXCEPTION 'complete_parent_binding';END IF;
 m:=public.research_complete_mapping_v2(old.payload->>'symbol');
 IF m IS NULL OR m->>'inventoryHash' IS DISTINCT FROM p_request->>'expectedArtifactManifestHash' OR m->>'sourceClosureHash' IS DISTINCT FROM p_request->>'expectedCalculatorExecutionHash' THEN RAISE EXCEPTION 'complete_mapping_unavailable';END IF;
 replay:=public.assert_research_input_preparation_v2(old.request,old.preparation_id,old.input_hash);
 RETURN replay;
END $$;
CREATE FUNCTION public.read_research_article_input_revision_v2(p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE parent jsonb; saved public.research_article_input_revisions_v2;
BEGIN
 parent:=public.research_complete_parent_v2(p_request);
 SELECT * INTO saved FROM public.research_article_input_revisions_v2 WHERE preparation_id=(p_request->>'preparationId')::uuid;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','absent','preparation',parent,'dispatchReady',false);END IF;
 IF saved.canonical_request IS DISTINCT FROM p_request OR saved.request_hash IS DISTINCT FROM public.research_complete_hash_v2(p_request) THEN RAISE EXCEPTION 'complete_replay_conflict';END IF;
 IF clock_timestamp()>=least((parent->'payload'->'originalJob'->>'leaseExpiresAt')::timestamptz,(parent->'payload'->'originalReservation'->>'leaseExpiresAt')::timestamptz) THEN RAISE EXCEPTION 'complete_lease_lost';END IF;
 RETURN to_jsonb(saved)||jsonb_build_object('status','sealed','replay',true,'dispatchReady',false);
END $$;
CREATE FUNCTION public.seal_research_article_input_revision_v2(p_request jsonb,p_calculation jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE parent jsonb; existing jsonb; m jsonb; p jsonb; f jsonb; projection jsonb; calc jsonb; material jsonb; known timestamptz; n timestamptz; rh text; ih text; charge integer; used_count bigint;used_bytes bigint;saved public.research_article_input_revisions_v2;gaps jsonb;
BEGIN
 existing:=public.read_research_article_input_revision_v2(p_request);IF existing->>'status'='sealed' THEN RETURN existing;END IF;
 parent:=existing->'preparation';p:=parent->'payload';m:=public.research_complete_mapping_v2(p->>'symbol');
 IF p_calculation IS NULL OR octet_length(p_calculation::text)>262144 THEN RAISE EXCEPTION 'complete_calculation_bound';END IF;
 known:=(p_calculation->>'artifactReadKnownAt')::timestamptz;
 PERFORM public.research_complete_schema_check_v2(p_calculation,m->'schema',known);
 IF p_calculation->>'sourceClosureHash' IS DISTINCT FROM m->>'sourceClosureHash' OR p_calculation->>'artifactInventoryHash' IS DISTINCT FROM m->>'inventoryHash' THEN RAISE EXCEPTION 'complete_calculation_mapping';END IF;
 f:=p_calculation->'financialMaterial';projection:=f->'projection';calc:=f->'calculation';
 IF octet_length(projection::text)>160000 THEN RAISE EXCEPTION 'complete_projection_bound';END IF;
 -- After bounded computation/validation, repeat all original fences under the same locks.
 parent:=public.research_complete_parent_v2(p_request);n:=clock_timestamp();
 IF NOT isfinite(known) OR known>n OR known<(m->>'modelCutoff')::timestamptz OR (parent->>'admitted_at')::timestamptz>n OR (parent->>'admitted_at')::timestamptz<n-interval '120 seconds' THEN RAISE EXCEPTION 'complete_freshness';END IF;
 gaps:=jsonb_build_array(jsonb_build_object('namespace','source','reason','source_coverage_incomplete'),jsonb_build_object('namespace','financial','reason','financial_source_live_rights_unverified'),jsonb_build_object('namespace','execution','reason','trusted_role_execution_unavailable'));
 SELECT gaps||jsonb_agg(jsonb_build_object('namespace','financial','reason',reason) ORDER BY ord) INTO gaps FROM jsonb_array_elements_text(projection->'gaps') WITH ORDINALITY a(reason,ord);
 IF jsonb_array_length(p->'sourceManifest')=0 THEN gaps:=gaps||jsonb_build_array(jsonb_build_object('namespace','source','reason','sources_not_selected'));END IF;
 material:=jsonb_build_object('schemaVersion','research-article-input-v2','assemblyStatus','complete','evidenceStatus','incomplete','producerAttribution','internal_controller_asserted',
 'preparation',jsonb_build_object('id',parent->'preparation_id','inputHash',parent->'input_hash'),
 'researchIdentity',jsonb_build_object('researchCompanyId',p->'researchCompanyId','symbol',p->'symbol','scope',p->'scope','snapshotHash',p->'snapshotHash','mappingDigest',p->'mappingDigest','stockId',p->'stockId'),
 'priority',jsonb_build_object('runId',p->'priorityRunId','inputHash',p->'priorityInputHash','discoveryCutoff',p->'discoveryCutoff'),
 'originalJob',p->'originalJob','originalReservation',p->'originalReservation','sources',jsonb_build_object('sealId',parent->'source_seal_id','manifest',p->'sourceManifest','coverage','incomplete'),
 'financial',jsonb_build_object('artifactInventory',m->'inventory','material',f),
 'hashes',jsonb_build_object('preparationInputHash',parent->'input_hash','artifactInventoryHash',public.research_complete_hash_v2(m->'inventory'),'modelHistoricalCanonicalHash',m->'historicalHash',
 'sourceManifestHash',public.research_complete_hash_v2(projection->'sourceManifest'),'projectionHash',public.research_complete_hash_v2(projection),'scenarioInputHash',public.research_complete_hash_v2(projection->'projected'->'scenarios'),'resultHash',public.research_complete_hash_v2(calc),'sourceClosureHash',m->'sourceClosureHash'),
 'clocks',jsonb_build_object('originalModelCutoff',m->'modelCutoff','originalPreparationAdmittedAt',parent->'admitted_at','artifactReadKnownAt',p_calculation->'artifactReadKnownAt','financialAdmittedAt',n,'researchCutoff',n),
 'gaps',gaps,'capabilities',jsonb_build_object('financialVerified',false,'dispatchReady',false,'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false,'historicalPITEligible',false));
 charge:=octet_length(convert_to(public.research_complete_canonical_v2(p_request),'UTF8'))+octet_length(convert_to(public.research_complete_canonical_v2(material),'UTF8'));
 SELECT count(*),coalesce(sum(logical_bytes),0) INTO used_count,used_bytes FROM (
 SELECT logical_bytes FROM public.research_input_preparations_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid
 UNION ALL SELECT logical_bytes FROM public.research_article_input_revisions_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid) history;
 IF used_count>=4 THEN RAISE EXCEPTION 'complete_count_bound';END IF;IF used_bytes+charge>524288 THEN RAISE EXCEPTION 'complete_byte_bound';END IF;
 IF clock_timestamp()>=least((p->'originalJob'->>'leaseExpiresAt')::timestamptz,(p->'originalReservation'->>'leaseExpiresAt')::timestamptz) THEN RAISE EXCEPTION 'complete_lease_lost';END IF;
 rh:=public.research_complete_hash_v2(p_request);ih:=public.research_complete_hash_v2(material);
 INSERT INTO public.research_article_input_revisions_v2(preparation_id,job_id,attempt,reservation_id,research_company_id,research_scope,snapshot_hash,request_hash,canonical_request,input_hash,canonical_payload,logical_bytes,admitted_at,research_cutoff,source_seal_id)
 VALUES((parent->>'preparation_id')::uuid,(parent->>'job_id')::uuid,(parent->>'attempt')::int,(parent->>'reservation_id')::uuid,(p->>'researchCompanyId')::uuid,'research_observed_v1',p->>'snapshotHash',rh,p_request,ih,material,charge,n,n,(parent->>'source_seal_id')::uuid) RETURNING * INTO saved;
 RETURN to_jsonb(saved)||jsonb_build_object('status','sealed','replay',false,'dispatchReady',false);
END $$;
DO $$ BEGIN
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.prepare_research_input_v2(jsonb)'::regprocedure) IS DISTINCT FROM '4836fbda90ab63490d24d425394244b85c8313d9b581dc738653be611940defb' OR (SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid='public.prepare_research_input_v2(jsonb)'::regprocedure) IS DISTINCT FROM 'research_input_preparation_owner_v2' THEN RAISE EXCEPTION 'complete_predecessor_not_exact';END IF;
END $$;
CREATE OR REPLACE FUNCTION public.prepare_research_input_v2(p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE j public.research_deep_jobs_v1; r public.research_model_reservations_v1;
 pri public.research_priority_runs_v1; snap public.research_observed_roster_snapshots_v1;
 old public.research_input_preparations_v2; saved public.research_input_preparations_v2;
 rh text; n timestamptz; docs jsonb; seal jsonb; material jsonb;
 used_count bigint; used_bytes bigint; charged_bytes integer; seal_manifest jsonb; seal_hash text; new_seal boolean:=false;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'input_preparation_read_committed_required'; END IF;
 IF p_request IS NULL OR jsonb_typeof(p_request)<>'object' OR octet_length(p_request::text)>8192
  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_request) key) IS DISTINCT FROM ARRAY['attempt','bundleId','jobId','owner','reservationId','scope','snapshotHash','sourceDocumentIds']
  OR p_request->>'scope' IS DISTINCT FROM 'research_observed_v1' OR p_request->'bundleId' IS DISTINCT FROM 'null'::jsonb
  OR jsonb_typeof(p_request->'owner') IS DISTINCT FROM 'string' OR p_request->>'owner' !~ '^[A-Za-z0-9:_-]{3,120}$'
  OR jsonb_typeof(p_request->'attempt') IS DISTINCT FROM 'number' OR p_request->>'attempt' !~ '^[1-3]$'
  OR jsonb_typeof(p_request->'sourceDocumentIds') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'input_preparation_shape'; END IF;
 IF jsonb_array_length(p_request->'sourceDocumentIds')>30 OR EXISTS(SELECT FROM jsonb_array_elements(p_request->'sourceDocumentIds') x WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$')
  OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_request->'sourceDocumentIds') x)<>jsonb_array_length(p_request->'sourceDocumentIds')
  OR jsonb_typeof(p_request->'jobId') IS DISTINCT FROM 'string' OR p_request->>'jobId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR jsonb_typeof(p_request->'reservationId') IS DISTINCT FROM 'string' OR p_request->>'reservationId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR jsonb_typeof(p_request->'snapshotHash') IS DISTINCT FROM 'string' OR p_request->>'snapshotHash' !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'input_preparation_shape'; END IF;
 -- One order: stable source fence, then existing global deep-job/model slot.
 PERFORM pg_advisory_xact_lock(610091002::bigint);
 PERFORM pg_advisory_xact_lock(2409,6002);
 SELECT * INTO j FROM public.research_deep_jobs_v1 WHERE job_id=(p_request->>'jobId')::uuid FOR SHARE;
 SELECT * INTO r FROM public.research_model_reservations_v1 WHERE reservation_id=(p_request->>'reservationId')::uuid FOR SHARE;
 n:=clock_timestamp();
 IF j.job_id IS NULL OR r.reservation_id IS NULL OR j.research_scope IS DISTINCT FROM 'research_observed_v1'
  OR j.status IS DISTINCT FROM 'running' OR j.attempts IS DISTINCT FROM (p_request->>'attempt')::integer
  OR j.lease_owner IS DISTINCT FROM p_request->>'owner' OR j.observed_snapshot_hash IS DISTINCT FROM p_request->>'snapshotHash'
  OR j.lease_expires_at IS NULL OR NOT isfinite(j.lease_expires_at) OR j.lease_expires_at<=n
  OR r.role IS DISTINCT FROM 'company_research' OR r.owner IS DISTINCT FROM j.lease_owner
  OR r.work_key IS DISTINCT FROM 'deep:'||j.job_id||':'||j.attempts
  OR r.started_at IS NULL OR NOT isfinite(r.started_at) OR r.started_at>n
  OR r.lease_expires_at IS NULL OR NOT isfinite(r.lease_expires_at) OR r.lease_expires_at<=n
  OR r.lease_expires_at>r.started_at+interval '30 minutes'
  OR NOT EXISTS(SELECT FROM public.research_deep_job_attempts_v1 a WHERE a.job_id=j.job_id AND a.attempt=j.attempts AND a.owner=j.lease_owner AND a.lease_expires_at=j.lease_expires_at AND a.claimed_at<=n)
  OR EXISTS(SELECT FROM public.research_model_completions_v1 c WHERE c.reservation_id=r.reservation_id)
 THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
 SELECT * INTO pri FROM public.research_priority_runs_v1 WHERE run_id=j.priority_run_id;
 SELECT * INTO snap FROM public.research_observed_roster_snapshots_v1 WHERE snapshot_hash=j.observed_snapshot_hash;
 IF pri.run_id IS NULL OR pri.research_scope IS DISTINCT FROM j.research_scope OR pri.observed_snapshot_hash IS DISTINCT FROM j.observed_snapshot_hash
  OR pri.as_of IS NULL OR NOT isfinite(pri.as_of) OR pri.as_of>n OR snap.snapshot_hash IS NULL OR snap.received_at IS NULL OR NOT isfinite(snap.received_at) OR snap.latest_observed_at IS NULL OR NOT isfinite(snap.latest_observed_at) OR snap.received_at>pri.as_of OR snap.latest_observed_at>pri.as_of
  OR NOT EXISTS(SELECT FROM public.research_observed_priority_store_receipts_v1 s WHERE s.run_id=pri.run_id AND s.stored_run_hash=encode(sha256(convert_to(to_jsonb(pri)::text,'UTF8')),'hex'))
  OR NOT EXISTS(SELECT FROM public.research_observed_roster_members_v1 m JOIN public.research_observed_companies_v1 c USING(research_company_id) WHERE m.snapshot_hash=snap.snapshot_hash AND m.research_company_id=j.research_company_id AND m.symbol=j.symbol AND c.symbol=j.symbol)
 THEN RAISE EXCEPTION 'input_preparation_lineage'; END IF;
 rh:=encode(sha256(convert_to(public.research_observed_canonical_json_v1(p_request),'UTF8')),'hex');
 SELECT * INTO old FROM public.research_input_preparations_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id AND request_hash=rh;
 IF FOUND THEN
  IF old.request IS DISTINCT FROM p_request THEN RAISE EXCEPTION 'input_preparation_replay_mismatch'; END IF;
  IF old.source_seal_id IS NOT NULL THEN PERFORM public.assert_research_source_seal_v2(old.source_seal_id); END IF;
  IF clock_timestamp()>=least(j.lease_expires_at,r.lease_expires_at) THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
  RETURN to_jsonb(old)||jsonb_build_object('replay',true,'dispatchReady',false);
 END IF;
 -- Original-unit history is permanent: expiry, invalidation and takeover never refund it.
 SELECT count(*),coalesce(sum(logical_bytes),0) INTO used_count,used_bytes FROM (SELECT logical_bytes FROM public.research_input_preparations_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id
  UNION ALL SELECT logical_bytes FROM public.research_article_input_revisions_v2 WHERE job_id=j.job_id AND attempt=j.attempts AND reservation_id=r.reservation_id) history;
 IF used_count>=4 THEN RAISE EXCEPTION 'input_preparation_count_bound'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'rowHash',encode(sha256(convert_to(to_jsonb(d)::text,'UTF8')),'hex')) ORDER BY d.id),'[]') INTO docs FROM public.source_raw_documents d WHERE p_request->'sourceDocumentIds' @> jsonb_build_array(d.id::text);
 IF jsonb_array_length(docs)<>jsonb_array_length(p_request->'sourceDocumentIds') THEN RAISE EXCEPTION 'input_preparation_source_missing'; END IF;
 IF jsonb_array_length(docs)>0 THEN
  -- Exact existing-seal lookup under the shared source fence; full receipt is charged only when new.
  SELECT jsonb_agg(jsonb_build_object('id',d.id::text,'rowHash',encode(sha256(convert_to(to_jsonb(d)::text,'UTF8')),'hex'),
   'root',public.research_source_root_v2(to_jsonb(d)),'publishedAt',to_jsonb(d)->'published_at',
   'observedAt',to_jsonb(d)->'collected_at','rights',d.metadata->>'rights_boundary') ORDER BY d.id) INTO seal_manifest
   FROM public.source_raw_documents d WHERE p_request->'sourceDocumentIds' @> jsonb_build_array(d.id::text);
  seal_hash:=encode(sha256(convert_to(jsonb_build_object('documents',seal_manifest,'cutoff',n)::text,'UTF8')),'hex');
  new_seal:=NOT EXISTS(SELECT FROM public.research_source_seals_v2 WHERE request_hash=seal_hash);
  seal:=public.seal_research_sources_v2(docs,n);
  IF seal->>'request_hash' IS DISTINCT FROM seal_hash THEN RAISE EXCEPTION 'input_preparation_seal_projection_changed'; END IF;
 END IF;
 -- Freeze DB-derived manifests; full original rows remain behind the private source seal.
 -- No supplied model output, financial facts, calculator or role identity is accepted here.
 material:=jsonb_build_object('schemaVersion','research-input-preparation-v2','researchCompanyId',j.research_company_id,'symbol',j.symbol,
  'scope',j.research_scope,'snapshotHash',snap.snapshot_hash,'mappingDigest',snap.mapping_digest,'stockId',j.stock_id,
  'priorityRunId',pri.run_id,'priorityInputHash',pri.input_hash,'discoveryCutoff',pri.as_of,'originalModelCutoff',NULL,'researchCutoff',n,
  'originalJob',jsonb_build_object('jobId',j.job_id,'attempt',j.attempts,'owner',j.lease_owner,'leaseExpiresAt',j.lease_expires_at),
  'originalReservation',jsonb_build_object('reservationId',r.reservation_id,'startedAt',r.started_at,'leaseExpiresAt',r.lease_expires_at),
  'sourceManifest',coalesce(seal->'documents','[]'),'sourceSelectionComplete',false,'financial',NULL,'calculator',NULL,
  'status','draft_incomplete','gaps',jsonb_build_array('financial_input_revision_missing','trusted_calculator_not_bound','original_model_not_selected','trusted_execution_authority_unavailable')||CASE WHEN jsonb_array_length(docs)=0 THEN jsonb_build_array('sources_not_selected') ELSE '[]'::jsonb END,
  'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false);
 charged_bytes:=public.research_input_preparation_bytes_v2(p_request,material,CASE WHEN new_seal THEN seal ELSE 'null'::jsonb END);
 IF used_bytes+charged_bytes>524288 THEN RAISE EXCEPTION 'input_preparation_byte_bound'; END IF;
 IF clock_timestamp()>=least(j.lease_expires_at,r.lease_expires_at) THEN RAISE EXCEPTION 'input_preparation_original_lease_lost'; END IF;
 INSERT INTO public.research_input_preparations_v2(job_id,attempt,reservation_id,request_hash,request,input_hash,payload,logical_bytes,source_seal_id,admitted_at)
 VALUES(j.job_id,j.attempts,r.reservation_id,rh,p_request,encode(sha256(convert_to(public.research_observed_canonical_json_v1(material),'UTF8')),'hex'),material,charged_bytes,(seal->>'seal_id')::uuid,n) RETURNING * INTO saved;
 RETURN to_jsonb(saved)||jsonb_build_object('replay',false,'dispatchReady',false);
END $$;
ALTER FUNCTION public.research_complete_canonical_v2(jsonb,integer) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.research_complete_canonical_v2(jsonb,integer) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.research_complete_hash_v2(jsonb) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.research_complete_hash_v2(jsonb) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.research_complete_schema_check_v2(jsonb,jsonb,timestamptz,integer) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.research_complete_schema_check_v2(jsonb,jsonb,timestamptz,integer) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.research_complete_mapping_v2(text) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.research_complete_mapping_v2(text) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.research_complete_parent_v2(jsonb) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.research_complete_parent_v2(jsonb) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.read_research_article_input_revision_v2(jsonb) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.read_research_article_input_revision_v2(jsonb) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION public.seal_research_article_input_revision_v2(jsonb,jsonb) OWNER TO research_input_preparation_owner_v2;
REVOKE ALL ON FUNCTION public.seal_research_article_input_revision_v2(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.read_research_article_input_revision_v2(jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.seal_research_article_input_revision_v2(jsonb,jsonb) TO service_role;
COMMIT;
